def evaluate(current_reputation, observation, my_history, round_num):
    """
    Update reputation using a moving average that is amplified by social consensus.
    """
    # Extract current action
    is_cooperate = observation['action'] == 'cooperate'

    # Compute social cooperation ratio from recent_window
    window = observation.get('recent_window', [])
    if window:
        coop_count = sum(1 for entry in window if entry['action'] == 'cooperate')
        coop_ratio = coop_count / len(window)
    else:
        coop_ratio = 0.5  # neutral if no observations

    # Base delta, scaled by social consensus
    if is_cooperate:
        delta = 0.5 * (1 + coop_ratio)   # more reward when others cooperate
    else:
        delta = -0.5 * (1 + coop_ratio)  # more punishment when others cooperate

    # Blend with previous reputation
    decay = 0.85
    new_rep = current_reputation * decay + (1 - decay) * delta
    return max(-1.0, min(1.0, new_rep))


